import { getModule } from './modules.js';

const core = {
  'What is Software Testing?': ['Software testing is the process of checking software to find problems and learn whether it meets its requirements.', 'A tester tries realistic inputs, observes what the product does, and compares the result with what users need.', 'Before a train ticket app is released, a tester books, changes, and cancels sample journeys to catch problems.', 'Try signing in with a valid account and a wrong password, then compare each result with the expected behavior.', ['Testing provides information about quality; it cannot prove that software has no bugs.', 'Checks can be manual, automated, or a mix.', 'Start from user needs and clear expected results.']],
  'Why is Testing Important?': ['Testing reduces the chance that users encounter failures and gives a team evidence for release decisions.', 'Finding a problem before release is usually easier and less costly than repairing it after customers rely on the feature.', 'A payment check can catch a duplicate charge before the checkout flow reaches real shoppers.', 'Test a checkout total, payment failure, and confirmation so customers are not charged incorrectly.', ['Protects user trust and business data.', 'Finds mismatches with requirements early.', 'Helps teams make informed release decisions.']],
  'Verification vs Validation': ['Verification checks whether work products follow their specification; validation checks whether the finished product solves the user’s real need.', 'Verification asks “Did we build it according to the design?” Validation asks “Did we build the right thing?”', 'Reviewing a form design against requirements is verification; asking a user to complete the form is validation.', 'Check the registration rules against the story, then ask a first-time user whether registration is understandable.', ['Verification often includes reviews and inspections.', 'Validation often includes executing the product with representative users.', 'Both activities support quality.']],
  'Error, Bug, Defect and Failure': ['An error is a human mistake; a defect is a flaw in a work product; a bug is a common name for a software defect; a failure is incorrect behavior seen while the software runs.', 'A person may make an error in a calculation, which puts a defect in code; users see a failure when the wrong total appears.', 'A tax-rate typo in code can cause a checkout total to be wrong for a customer.', 'A discount rule defect may cause the cart to show a different total from the order confirmation.', ['Cause and effect can form a chain.', 'A defect may stay hidden until a particular condition triggers it.', 'Teams often use “bug” and “defect” interchangeably.']],
  'QA vs QC': ['Quality assurance (QA) improves the process used to build software; quality control (QC) checks the product for problems.', 'QA is process-focused and preventive; QC is product-focused and detective. Testing is one QC activity.', 'A team improves its code review process as QA, then runs release checks as QC.', 'Adding a checklist to the team’s review process is QA; checking the finished login form is QC.', ['QA aims to prevent defects.', 'QC aims to find defects in deliverables.', 'Both contribute to quality.']],
  'Tester vs Developer': ['Developers create and maintain software; testers evaluate it, expose risk, and share evidence about its behavior.', 'The roles collaborate: developers may test their code, while testers bring an independent view and investigate user workflows.', 'A developer builds a search filter; a tester checks boundaries, empty results, and confusing error states.', 'Both roles can pair on an issue: the tester reproduces it and the developer diagnoses and fixes it.', ['These are complementary responsibilities, not competing roles.', 'Both need clear communication.', 'Many teams share responsibility for quality.']],
  'SDLC': ['The software development life cycle (SDLC) is the set of stages a team uses to plan, build, check, release, and maintain software.', 'It gives work a structure, from understanding a need through supporting the delivered product.', 'A team plans a booking feature, designs it, implements it, tests it, releases it, and monitors usage.', 'An account feature moves from requirements and design through implementation, testing, release, and later fixes.', ['Stages can be sequential or iterative.', 'Testing appears throughout a healthy SDLC.', 'Feedback can send work back to an earlier stage.']],
  'Waterfall Model': ['Waterfall is a sequential approach where a team completes one major project phase before moving to the next.', 'It is easiest to use when needs are stable and changes are uncommon; late feedback can be expensive.', 'A contract project with fixed requirements may agree on design before construction begins.', 'A team may document all checkout requirements before implementation, so changes later need formal review.', ['Phases are planned in sequence.', 'Test execution is often later in the schedule.', 'Frequent requirement changes make it harder to manage.']],
  'Agile Model': ['Agile is an iterative way of delivering software in small increments and using feedback to adapt the plan.', 'Instead of waiting for one large release, the team learns from each short cycle and adjusts priorities.', 'A team releases a small search improvement, reviews feedback, and then improves filters in the next cycle.', 'A login improvement is delivered in a sprint, tested with the team, and refined from user feedback.', ['Work is delivered in increments.', 'People collaborate frequently.', 'Plans can adapt as the team learns.']],
  'V-Model': ['The V-Model pairs each development stage with a corresponding test level planned alongside it.', 'The left side defines and designs the solution; the right side checks the matching work product.', 'System requirements can be paired with acceptance testing, while component design is paired with unit testing.', 'A checkout requirement is linked early to an acceptance check, making coverage easier to trace.', ['Testing is planned early.', 'Each development level has a related test level.', 'It emphasizes traceability and defined requirements.']],
  'Software Testing Life Cycle': ['The software testing life cycle (STLC) is the sequence of activities a testing team uses to plan, design, run, and close testing work.', 'Typical steps include analyzing requirements, planning, preparing cases and data, setting up the environment, executing, and reporting.', 'For a new profile page, a tester reviews the story, plans checks, prepares accounts, executes cases, and reports results.', 'For a password reset change, the team can track work from requirement analysis through test closure.', ['STLC describes testing activities.', 'The exact steps vary between teams.', 'Risks and defects should be communicated throughout.']],
  'Manual Testing': ['Manual testing is a person checking software by interacting with it and evaluating the results.', 'It is useful when human judgment, exploration, or visual feedback matters.', 'A tester tries a new editor and notices that its save button is hard to find.', 'Manually inspect whether the profile form gives a clear message when required fields are missing.', ['No test script has to run the check.', 'It is flexible for exploratory work.', 'Repeated checks can be slow and inconsistent.']],
  'Automation Testing': ['Automation testing uses code or tools to run checks and compare actual results with expected results.', 'Automation is most useful for repeatable checks that the team needs to run often.', 'A short automated test signs in and verifies that the home page appears after each code change.', 'Automate a stable registration flow so it can be checked on every build.', ['Automation supports repeatability and speed.', 'Tests still need to be designed and maintained.', 'A tool does not replace thoughtful test coverage.']],
  'Functional Testing': ['Functional testing checks what a system does against its stated features and business rules.', 'It focuses on inputs, actions, and outputs rather than speed or appearance alone.', 'A tester checks that applying a valid coupon changes the order total correctly.', 'Check that a user can update their name and that the saved value appears on their profile.', ['Use requirements to define expected behavior.', 'Include normal and invalid inputs.', 'It can be done at several test levels.']],
  'Non-functional Testing': ['Non-functional testing evaluates qualities such as speed, security, usability, reliability, and capacity.', 'It asks how well the product works, rather than only whether a feature exists.', 'A team checks that a page remains responsive with many visitors.', 'Check whether checkout remains usable on a narrow phone screen and under a slow connection.', ['Quality attributes matter to real users.', 'Choose measurable goals where possible.', 'A feature can work correctly but still have poor quality.']],
  'Black-box Testing': ['Black-box testing checks externally visible behavior without relying on knowledge of the internal code.', 'The tester supplies inputs and evaluates outputs using requirements or expected user behavior.', 'A tester enters a valid and invalid promo code without inspecting the calculation code.', 'Check a search form’s input and result without looking at its implementation.', ['Focus is on behavior at the interface.', 'Can be used at many test levels.', 'Good requirements help define expected results.']],
  'White-box Testing': ['White-box testing uses knowledge of internal code or structure to design and evaluate checks.', 'The tester can target code branches, paths, or conditions that are otherwise easy to miss.', 'A developer adds checks for both outcomes of a tax calculation condition.', 'A test exercises both the “signed in” and “guest” branches of a checkout handler.', ['Requires insight into implementation.', 'Code coverage can show which parts ran.', 'Coverage alone does not prove the code is correct.']],
  'Gray-box Testing': ['Gray-box testing combines external behavior checks with partial knowledge of the system’s internals.', 'Knowing a little about data flow or architecture can help choose stronger tests.', 'A tester who knows that a basket is stored in a session checks what happens when the session expires.', 'Knowing the app caches profiles, test whether edits appear after refresh and sign-in on another device.', ['Uses partial internal knowledge.', 'Still checks behavior from a user or interface perspective.', 'Useful for investigating integrations and data flows.']],
  'Unit Testing': ['Unit testing checks a small, isolated piece of software, such as one function or class.', 'Small tests help developers find mistakes close to where they were introduced.', 'A test checks that a price-formatting function turns 12.5 into the expected currency string.', 'Check the discount calculation function separately from the page that displays it.', ['Usually fast and focused.', 'Often written by developers.', 'Dependencies may be replaced with simple test doubles.']],
  'Integration Testing': ['Integration testing checks whether connected components or services work together correctly.', 'A component may pass its own checks but still send or receive data incorrectly from another component.', 'Check that an order service saves a payment result returned by a payment service.', 'Verify that a registration form sends the right data to the account service and handles its response.', ['Focuses on boundaries between parts.', 'Can reveal data or interface mismatches.', 'May run with real or simulated dependencies.']],
  'System Testing': ['System testing evaluates a complete integrated system against its requirements.', 'The goal is to understand whether the whole product behaves correctly in a representative environment.', 'A tester completes a journey from account creation through booking confirmation.', 'Run the complete product flow from login to saving a new address.', ['Tests the whole system.', 'Often uses black-box techniques.', 'Should reflect realistic environments and use cases.']],
  'Acceptance Testing': ['Acceptance testing checks whether a product or feature is ready for acceptance against agreed criteria.', 'It helps stakeholders decide whether the solution delivers the expected business value.', 'A client confirms that the report export matches the agreed format and content.', 'A product owner checks that the checkout meets the story’s acceptance criteria.', ['Criteria should be agreed before evaluation.', 'Can involve business users or customers.', 'It supports a release or acceptance decision.']],
  'UAT': ['User acceptance testing (UAT) is acceptance testing performed by intended users or business representatives.', 'Users try realistic tasks to confirm that the product supports their work.', 'A support team checks a new ticket workflow before it replaces the old one.', 'Store staff try the new inventory screen with realistic product updates before launch.', ['Uses business-relevant scenarios.', 'Usually happens near a release.', 'Feedback can uncover workflow gaps.']],
  'Smoke Testing': ['Smoke testing is a quick set of checks that decides whether a build is stable enough for deeper testing.', 'It covers the most important paths, not every detail.', 'After a deployment, a tester confirms that the app opens, users can sign in, and a main page loads.', 'Check that users can sign in and reach the cart before running the full shopping suite.', ['Broad and shallow checks.', 'Often runs on a new build.', 'A failure can stop further testing on that build.']],
  'Sanity Testing': ['Sanity testing is a focused check that a particular change or fix behaves sensibly.', 'It gives quick confidence in a narrow area before wider regression checks.', 'After a date-format fix, the tester checks the corrected date field and nearby behavior.', 'After correcting a coupon bug, verify that the coupon applies correctly to a matching order.', ['Narrow and change-focused.', 'Often performed after a small update.', 'Terminology can vary between teams.']],
  'Regression Testing': ['Regression testing checks that recent changes have not broken existing behavior.', 'It revisits important working features after code or configuration changes.', 'After changing account settings, rerun checks for sign-in, profile edits, and password reset.', 'After changing tax calculation, recheck totals, discounts, refunds, and order confirmation.', ['Targets side effects of change.', 'A stable suite can be automated.', 'Prioritize high-risk user journeys.']],
  'Retesting': ['Retesting runs a check that previously failed to confirm a reported defect has been fixed.', 'Use the original reproduction steps and expected result to verify the correction.', 'After a developer fixes a broken export, repeat the exact export steps that exposed the issue.', 'Repeat the steps for the fixed login lockout defect and verify the account can sign in as intended.', ['Confirms a specific fix.', 'Uses the original failing conditions.', 'Regression checks may follow to look for side effects.']],
  'Exploratory Testing': ['Exploratory testing combines learning, test design, and execution as the tester investigates the product.', 'The tester follows useful observations rather than only executing a fixed script.', 'While exploring a map, a tester notices that changing filters and zoom quickly creates stale results.', 'Explore the cart by changing quantities, removing products, refreshing, and using browser navigation.', ['Uses curiosity and observation.', 'Notes and a time-box can help keep focus.', 'Useful for uncovering unexpected behavior.']],
  'Ad-hoc Testing': ['Ad-hoc testing is informal testing without detailed written test cases, guided by experience and intuition.', 'A tester tries likely actions to discover obvious issues quickly.', 'A tester clicks around a new settings page and notices that a destructive action has no confirmation.', 'Try unusual sequences on the profile page, such as saving twice or navigating away mid-edit.', ['Fast and informal.', 'Harder to repeat or measure.', 'Record any useful defect and reproduction steps.']],
  'End-to-End Testing': ['End-to-end testing checks a complete user journey across the components needed to deliver an outcome.', 'It verifies that the parts work together from the user’s starting point to the final result.', 'A user searches for a trip, pays, and receives a booking confirmation.', 'Follow a shopper from product search through payment and order confirmation.', ['Covers realistic workflows.', 'Can reveal integration problems.', 'Often slower and more fragile than focused tests.']],
  'Compatibility Testing': ['Compatibility testing checks that software behaves acceptably across supported devices, browsers, operating systems, or configurations.', 'The goal is to catch differences that appear only in a particular setup.', 'A team checks a booking page in supported desktop and mobile browsers.', 'Check the sign-in page in the browsers and phone sizes listed in the support policy.', ['Start with the combinations users actually need.', 'Include device and browser differences.', 'Automated and manual checks can complement each other.']],
  'Equivalence Partitioning': ['Equivalence partitioning divides input values into groups expected to behave similarly, then tests representative values from each group.', 'Instead of trying every age, choose a valid example and examples from invalid groups.', 'For an age field accepting 18–65, test one value below, one within, and one above the range.', 'For a coupon accepting codes with 6–10 characters, choose one valid-length and representative too-short and too-long codes.', ['Identify valid and invalid partitions.', 'Choose a representative from each group.', 'Pair well with boundary value analysis.']],
  'Boundary Value Analysis': ['Boundary value analysis focuses tests on the edges of an accepted input range, where mistakes are common.', 'For a range, test at the minimum and maximum and just on either side.', 'For a field accepting 1–99 items, test 0, 1, 2, 98, 99, and 100.', 'If a password needs 8–24 characters, test lengths 7, 8, 9, 23, 24, and 25.', ['Boundaries include edges and just-outside values.', 'Works well with equivalence partitions.', 'Most useful for ordered numeric or length ranges.']],
  'Decision Table Testing': ['Decision table testing lays out combinations of conditions and the action expected for each combination.', 'It is useful when several rules interact and examples are easy to overlook.', 'A shipping fee depends on membership and order total; a table lists each combination and fee.', 'Combine coupon validity, cart minimum, and membership status to check which discount applies.', ['List conditions and possible outcomes.', 'Map combinations to expected actions.', 'Can reveal missing or conflicting business rules.']],
  'State Transition Testing': ['State transition testing checks how a system moves between states after events.', 'It focuses on allowed and forbidden transitions, not just isolated screens.', 'An account moves from active to locked after repeated failed sign-in attempts.', 'Check that an order moves from pending to shipped, and cannot jump directly from draft to refunded.', ['Identify states and triggering events.', 'Test valid transitions and important invalid ones.', 'Useful for workflows and status-driven systems.']],
  'Use Case Testing': ['Use case testing derives checks from realistic user goals and the steps needed to achieve them.', 'It covers the main success path and alternative or error paths.', 'For booking travel, check searching, selecting a trip, paying, and receiving confirmation.', 'Use the “buy a product” journey to check a normal order plus alternatives such as an empty cart or declined payment.', ['Start with a user goal.', 'Include alternate flows.', 'Connects tests to real tasks.']],
  'Performance Testing': ['Performance testing measures how a system behaves in terms of responsiveness, throughput, and resource use.', 'It helps answer whether the application feels fast enough under expected conditions.', 'A team measures how long a report takes to load while observing server resource use.', 'Measure search response time while representative users browse the catalog.', ['Define workload and measurable goals.', 'Observe response time and resources.', 'Use results to find bottlenecks.']],
  'Load Testing': ['Load testing checks system behavior under an expected or specified amount of work.', 'It helps determine whether normal or peak anticipated traffic can be handled.', 'A ticketing site is tested with the expected number of people browsing before a popular event.', 'Simulate a normal lunch-hour shopping peak and measure checkout response times.', ['Use realistic expected traffic.', 'Measure throughput and response time.', 'Compare results with service goals.']],
  'Stress Testing': ['Stress testing pushes a system beyond expected capacity to learn how it fails and recovers.', 'It looks for limits, instability, and whether the system recovers safely after overload.', 'A team increases requests past normal peak traffic and watches for recovery after the spike ends.', 'Send more concurrent checkout requests than forecast and verify that the service recovers without losing orders.', ['Exceeds normal operating conditions.', 'Observe failure behavior and recovery.', 'Protect data while finding system limits.']],
  'Security Testing': ['Security testing looks for weaknesses that could let someone access data or perform actions they should not.', 'It checks how the system handles identity, permissions, input, and sensitive information.', 'A tester confirms that one account cannot view another person’s private documents.', 'Check that signed-out users cannot open an account page by pasting its URL.', ['Check authentication and authorization.', 'Handle sensitive data carefully.', 'Follow approved security scope and practices.']],
  'Usability Testing': ['Usability testing evaluates how easily intended users can understand and use a product to complete tasks.', 'Watch people attempt realistic tasks and note confusion, delays, and mistakes.', 'A participant tries to find a past receipt while the observer records where they hesitate.', 'Ask a first-time user to update their address without coaching and observe the experience.', ['Use representative users and tasks.', 'Observe behavior, not only opinions.', 'Findings can improve labels and workflows.']],
  'Reliability Testing': ['Reliability testing checks whether a system continues to operate consistently over time and under stated conditions.', 'It looks for failures that happen after long use, repeated operation, or environmental changes.', 'A team runs a service continuously and records unexpected restarts or failed requests.', 'Leave a reporting dashboard running and refresh it repeatedly to find intermittent failures.', ['Run under defined conditions.', 'Look for intermittent failures.', 'Stability over time matters.']],
  'Scalability Testing': ['Scalability testing checks how well a system handles growth in users, data, or work as resources change.', 'It helps a team understand whether capacity can grow without unacceptable performance loss.', 'A team increases traffic and storage size to see whether a service can grow smoothly.', 'Test whether product search remains responsive as the catalog grows from thousands to millions of items.', ['Increase workload or resources systematically.', 'Track performance and cost.', 'Find the limits to future growth.']],
  'Test Scenario': ['A test scenario is a high-level statement of a behavior or user journey that should be checked.', 'Scenarios describe what to test; test cases add the exact steps and data.', '“Check password reset” is a scenario that can lead to several detailed cases.', '“Verify that shoppers can manage a cart” can become scenarios for add, update, remove, and empty-cart behavior.', ['Describes a test area or goal.', 'Usually concise and broad.', 'Can be expanded into multiple cases.']],
  'Test Case': ['A test case is a documented set of conditions, inputs, actions, and expected results for checking one behavior.', 'A clear case lets someone repeat the check and decide whether it passed.', 'A sign-in case lists the account, steps, and expected home page.', 'A cart test names a product, quantity, action, and expected subtotal.', ['Has clear preconditions and steps.', 'Includes test data and expected results.', 'Should be repeatable.']],
  'Test Case Structure': ['A test case structure is the set of fields used to describe and track a test consistently.', 'Common fields include an ID, title, preconditions, steps, data, expected result, actual result, and status.', 'A team uses the same fields so anyone can run and review its checks.', 'For a password reset case, record the starting account state, email, actions, expected message, and outcome.', ['A shared format improves clarity.', 'Keep steps specific and observable.', 'Teams can adapt fields to their workflow.']],
  'Preconditions': ['Preconditions are the setup facts that must be true before a test begins.', 'They make sure the starting state is clear, so results are repeatable.', 'A profile-edit test may require an active signed-in account.', 'Before testing a saved cart, make sure the user is signed in and the cart has one item.', ['Describe required starting data or state.', 'Avoid hidden setup.', 'Keep setup separate from action steps.']],
  'Test Steps': ['Test steps are the ordered actions a person or script performs to exercise a behavior.', 'Each step should be clear enough that another person can follow it without guessing.', 'Open the form, enter a valid email, submit it, then check for a confirmation message.', 'Sign in, open Cart, change quantity to two, and select Update.', ['Use one observable action per step.', 'Keep the order explicit.', 'Pair steps with an expected outcome.']],
  'Test Data': ['Test data is the input information used to execute a test.', 'A thoughtful set includes normal, boundary, and invalid values that reflect likely use.', 'A username field might use a typical name, an empty value, and the maximum allowed length.', 'Use one valid card, one declined test card, and an expired date in payment checks.', ['Use representative and edge-case values.', 'Protect private or production data.', 'Make data setup repeatable.']],
  'Expected Result': ['The expected result describes what should happen if the software behaves correctly.', 'It should be specific and observable so a pass or fail is clear.', 'After a successful sign-in, the account home page appears and shows the correct name.', 'After adding an item, the cart badge increases and the product appears in the cart.', ['Base it on requirements or agreed behavior.', 'Avoid vague words like “works.”', 'Compare it with the actual result.']],
  'Actual Result': ['The actual result records what happened when the test was run.', 'Compare it with the expected result; a mismatch may need investigation or a defect report.', 'The expected page appears, but the displayed account name is blank.', 'The cart badge changes to two, but the cart page still shows only one product.', ['Capture observed behavior honestly.', 'Include useful evidence.', 'A mismatch may indicate a defect.']],
  'Positive Testing': ['Positive testing checks that software accepts valid inputs and completes a normal, allowed action.', 'It confirms the intended path works for expected data.', 'Enter a correctly formatted email and password and confirm the account opens.', 'Submit a valid shipping address and confirm it is saved.', ['Use valid inputs.', 'Check the normal success path.', 'Pair it with negative checks for broader coverage.']],
  'Negative Testing': ['Negative testing checks that software handles invalid, unexpected, or disallowed inputs safely.', 'It confirms the application rejects bad data and explains what the user can do next.', 'Try submitting an empty required field and confirm a helpful validation message appears.', 'Use an expired coupon and verify that no discount is applied and the reason is clear.', ['Try invalid and unexpected values.', 'Check error handling and data safety.', 'Messages should help users recover.']],
  'What is a Bug?': ['A bug is a flaw that makes software behave differently from its intended or required behavior.', 'A bug can be in code, configuration, data, or the way components interact.', 'A search page shows the wrong products when a filter is selected.', 'A user sees a zero balance even though the account has completed purchases.', ['Record evidence and impact.', 'Reproduce the issue where possible.', 'Not every unusual behavior is necessarily a bug; compare against expectations.']],
  'Bug Life Cycle': ['The bug life cycle describes the stages a defect report may pass through from discovery to closure.', 'A common flow is New, triaged, Assigned, Fixed, Retested, and Closed; exact names differ by team.', 'A tester reports a crash, a developer fixes it, and the tester verifies the change before closure.', 'A cart total defect is filed, assigned, fixed, retested, and closed once the expected total is confirmed.', ['Status shows current ownership and action.', 'A failed retest may reopen the defect.', 'Teams can customize their workflow.']],
  'Severity vs Priority': ['Severity describes how much a defect harms the system; priority describes how soon the team should address it.', 'A typo on the homepage may have low severity but high priority before a launch; a rare crash may be severe but less urgent.', 'A broken payment flow is usually high severity and high priority.', 'A minor color mismatch in a rarely visited internal page could be low severity and lower priority.', ['Severity is impact.', 'Priority is urgency or order of work.', 'Business context affects priority.']],
  'Bug Report': ['A bug report is a clear record of an observed problem, including how to reproduce it and what should have happened.', 'A good report helps another person confirm and investigate the issue without guesswork.', 'Report the browser, account state, steps, expected and actual results, and a screenshot of the failure.', 'For a failed order, include the cart contents, steps to submit, expected total, actual total, and useful console or screen evidence.', ['Use a concise descriptive title.', 'Include reproducible steps and environment.', 'Explain expected versus actual behavior.']],
  'Reproducing Bugs': ['Reproducing a bug means repeating the conditions and actions that make the problem happen.', 'Reliable reproduction helps a team confirm the issue and test its fix.', 'Repeat the same device, account, and steps that produced a blank report.', 'Retry the failing checkout with the same product, coupon, and address to identify the trigger.', ['Capture starting conditions.', 'Change one factor at a time.', 'Record whether the problem is consistent.']],
  'Defect Statuses': ['Defect statuses communicate where a bug report sits in the team’s workflow.', 'Statuses such as New, Assigned, In Progress, Fixed, Retest, Reopened, and Closed describe ownership and next steps.', 'A defect marked “Ready for retest” tells the tester that a fix is available to verify.', 'A checkout issue marked “Reopened” means the retest still found the same problem.', ['Use the team’s defined status meanings.', 'Statuses should reflect real work.', 'A status helps coordinate follow-up.']],
  'Agile': ['Agile is a set of values and approaches that favor collaboration, working software, customer feedback, and responding to change.', 'Teams deliver small slices, learn, and adjust rather than relying only on a long fixed plan.', 'A team releases a simpler checkout first, learns from users, then improves it in later cycles.', 'The team tests a small profile update in the sprint and uses feedback to refine the next change.', ['Frequent feedback guides decisions.', 'Quality is shared by the team.', 'Working increments make progress visible.']],
  'Scrum': ['Scrum is a lightweight framework for teams to organize work into short sprints and inspect progress regularly.', 'It defines accountabilities, events, and artifacts that help the team coordinate.', 'A Scrum team plans a sprint, meets briefly each day, reviews the increment, and reflects on improvements.', 'Testers join sprint planning and daily collaboration to make quality work visible.', ['Work is planned in sprints.', 'The team inspects and adapts.', 'Scrum gives structure without prescribing every engineering practice.']],
  'Sprint': ['A sprint is a fixed-length period in Scrum during which a team works toward a useful increment.', 'The team selects a goal and collaborates to complete, test, and review the work.', 'During a two-week sprint, a team delivers a tested saved-address feature.', 'A sprint goal might be to let customers update their delivery details safely.', ['Has a clear goal and time box.', 'Testing happens during the sprint.', 'The increment should meet the team’s quality expectations.']],
  'Product Backlog': ['The product backlog is an ordered list of product work, improvements, and fixes.', 'The product owner and team refine items so the most valuable work is understood and ready.', 'A backlog may contain payment updates, accessibility improvements, and reported defects.', 'A team prioritizes secure password reset ahead of a lower-impact visual polish task.', ['Items are ordered by value and other needs.', 'Details can evolve as the team learns.', 'Refinement helps prepare upcoming work.']],
  'User Story': ['A user story is a short description of a capability from the perspective of someone who needs it.', 'It often explains the user, their goal, and the value so the team can discuss behavior together.', '“As a traveler, I want to save a trip so I can book it later.”', '“As a shopper, I want to save my cart so I can return to it tomorrow.”', ['Describe a user goal and value.', 'Invite discussion rather than act as a full specification.', 'Acceptance criteria make expected behavior clearer.']],
  'Acceptance Criteria': ['Acceptance criteria are the conditions a feature must meet to be accepted as complete.', 'They turn a broad request into observable outcomes the team can discuss and test.', 'A reset link works once, expires after a set period, and shows a useful message for an invalid link.', 'A cart preserves products after refresh and updates totals when quantities change.', ['Keep criteria clear and testable.', 'Agree on them with relevant stakeholders.', 'Use them to guide examples and acceptance checks.']],
  'Daily Stand-up': ['A daily stand-up is a short team sync to coordinate progress and surface blockers.', 'It is for collaboration and adjustment, not a detailed status report to a manager.', 'A tester mentions a blocked test environment so the team can resolve it quickly.', 'The tester flags that a payment sandbox is unavailable before the team’s planned checks.', ['Keep it brief and focused.', 'Surface blockers early.', 'Follow up complex discussions separately.']],
  'Sprint Planning': ['Sprint planning is the event where the team agrees on a sprint goal and selects work it can realistically complete.', 'The team discusses value, capacity, risks, and how it will approach the work.', 'A tester helps identify test data and environment needs before a new search story enters the sprint.', 'The team decides how it will verify the saved-cart story before committing to the sprint goal.', ['Align work with a goal.', 'Consider testing effort and risk.', 'Plan collaboratively based on capacity.']],
  'Sprint Review': ['A sprint review is a collaborative look at the increment and a discussion of what to do next.', 'Stakeholders give feedback on working product behavior and future priorities.', 'The team demonstrates a new filter and gathers feedback on whether it matches user expectations.', 'Show the completed account recovery flow and ask support staff for feedback.', ['Inspect working outcomes.', 'Invite stakeholder feedback.', 'Use what is learned to adapt the backlog.']],
  'Retrospective': ['A retrospective is a team meeting to reflect on how the work went and choose improvements for the next cycle.', 'The focus is on process and collaboration, not blame.', 'The team agrees to prepare test data earlier after it caused repeated delays.', 'After a rushed release, the team adds a clearer test-environment handoff to its process.', ['Discuss what helped and what hindered.', 'Choose a small actionable improvement.', 'Create a safe, blame-free conversation.']],
  'Tester Role in Agile': ['In Agile, testers collaborate throughout planning, development, and feedback to help the team build quality in.', 'A tester clarifies examples, explores risk, automates useful checks, and shares findings early.', 'A tester helps refine a story, pairs on examples, explores the feature, and reports risk before sprint review.', 'The tester helps define cart edge cases while the feature is being designed, not only after coding ends.', ['Quality is shared across the team.', 'Testing begins early and continues.', 'Fast feedback helps the team adapt.']],
  'What is an API?': ['An API is a defined way for software components to request information or actions from one another.', 'A client sends a request; a service processes it and returns a response.', 'A weather app asks a weather service for the forecast in a city.', 'A web page asks an account service to load the signed-in user’s profile.', ['Defines an interface between systems.', 'Requests and responses carry data.', 'APIs can be checked independently from the user interface.']],
  'What is Automation Testing?': ['Automation testing uses scripts or tools to run repeatable checks and compare actual behavior with expected results.', 'A test script can perform the same actions and checks whenever the application changes.', 'A saved browser test signs in and verifies that the account page appears after each update.', 'Automate a stable registration journey so it can run after every build.', ['Automate valuable repeated checks.', 'Scripts need thoughtful design and upkeep.', 'Automation and manual exploration work well together.']],
  'REST API': ['A REST API is a web API style that organizes resources and uses standard HTTP methods to interact with them.', 'A client might read, create, update, or remove a resource using a URL and a method.', 'A travel service exposes trip resources that clients can read and book.', 'A shopping app can request product resources and create an order through HTTP endpoints.', ['Resources are addressed by URLs.', 'HTTP methods express the action.', 'Responses often contain JSON and a status code.']],
  'GET': ['GET requests retrieve a representation of a resource and should not change server state.', 'Use it to read data, then check the status, response body, and headers.', 'GET /products returns a list of products.', 'GET /api/cart returns the current user’s cart items.', ['Used to read information.', 'Check expected status and response structure.', 'Repeated reads should not create or modify data.']],
  'POST': ['POST requests submit data, often to create a resource or trigger an action.', 'Check valid and invalid bodies, response status, and whether the result was created as expected.', 'POST /orders submits a new order.', 'POST /api/login sends credentials and returns a session result.', ['Often creates or processes data.', 'Can have side effects.', 'Verify validation and duplicate-submission behavior.']],
  'PUT': ['PUT requests replace a resource representation at a known location, according to the API contract.', 'Check that the full submitted representation is stored and that repeating the request behaves as expected.', 'PUT /users/42 updates the complete profile record.', 'PUT /api/profile replaces the profile fields supplied by the client.', ['Usually represents full replacement.', 'Confirm behavior in the API documentation.', 'Check omitted fields and repeated requests.']],
  'PATCH': ['PATCH requests apply a partial update to a resource.', 'Use it when changing selected fields without sending the entire resource.', 'PATCH /users/42 changes only the display name.', 'PATCH /api/cart/items/8 changes an item quantity while preserving other cart details.', ['Targets a partial change.', 'Check untouched fields remain unchanged.', 'Validate invalid or missing fields.']],
  'DELETE': ['DELETE requests ask a service to remove a resource or make it unavailable.', 'Check authorization, the response, and what later reads show.', 'DELETE /saved-trips/7 removes one saved trip.', 'DELETE /api/cart/items/8 removes the selected item from the cart.', ['Used to remove or deactivate data.', 'Check access permissions.', 'Confirm the resource no longer appears as expected.']],
  'HTTP Status Codes': ['HTTP status codes summarize the outcome of an HTTP request.', 'Common groups are 2xx success, 3xx redirection, 4xx client/request issues, and 5xx server issues.', 'A successful read may return 200; a missing resource may return 404.', 'A created order may return 201, while an unauthenticated request may return 401.', ['Check status as well as response body.', 'Codes have standard meanings.', 'The API contract defines the expected code.']],
  'Headers': ['HTTP headers carry metadata about a request or response, such as content type, authorization, and caching rules.', 'They describe how data should be handled without placing that information in the body.', 'Content-Type tells a service that the submitted body is JSON.', 'An API request may send an authorization token and Accept: application/json.', ['Headers are key-value metadata.', 'Check required and sensitive headers.', 'Header names and values can affect behavior.']],
  'Request Body': ['The request body is the data sent with an HTTP request, often for creating or updating something.', 'Check required fields, data types, allowed values, and how invalid bodies are rejected.', 'A sign-up request body contains an email and password.', 'An order body contains item identifiers, quantities, and a delivery address.', ['Validate fields and types.', 'Do not send unnecessary sensitive data.', 'Confirm useful errors for invalid input.']],
  'Response Body': ['The response body is the data a service returns after processing a request.', 'Check its structure, field values, and consistency with the response status.', 'A product response contains an ID, name, price, and availability.', 'A cart response returns item quantities and a calculated subtotal.', ['Validate data and structure.', 'Check for missing or incorrect fields.', 'Avoid exposing private details.']],
  'JSON': ['JSON is a text format for representing structured data with objects, arrays, strings, numbers, booleans, and null.', 'It is commonly used for exchanging data between web clients and APIs.', 'A product can be represented as {"name":"Mug","price":12.5}.', 'Check that a profile API returns correctly named fields and the expected value types.', ['Objects use key-value pairs.', 'Arrays contain ordered values.', 'Types and nesting matter.']],
  'API Authentication': ['API authentication is the process of checking who or what is making a request.', 'Tests should confirm that valid credentials work and missing, invalid, or expired credentials are rejected.', 'A service accepts a valid token and rejects a revoked one.', 'Try reading a private order with a valid token, no token, and another user’s token.', ['Authentication establishes identity.', 'Authorization controls permitted actions.', 'Never expose real secrets in test output.']],
  'Postman Basics': ['Postman is a tool for sending API requests, inspecting responses, and organizing repeatable API checks.', 'You can set a URL, method, headers, body, send a request, and review the response.', 'Send GET /products, then inspect status, timing, headers, and returned JSON.', 'Create a request for POST /api/login with a test account and check the response fields.', ['Choose method and URL.', 'Set headers and a body when needed.', 'Save useful requests and avoid real credentials.']],
  'Database Basics': ['A database stores organized information so an application can retrieve and update it reliably.', 'Tables often hold rows of related records, while keys connect records across tables.', 'An online shop stores customers, products, and orders in related tables.', 'A cart and its order records can be checked in the database after checkout.', ['Understand tables, rows, and columns.', 'Relationships connect records.', 'Use safe test data and environments.']],
  'SQL Basics': ['SQL is a language for querying and changing data in relational databases.', 'A tester can use SQL to inspect records and verify what an application saved.', 'A SELECT statement reads matching order rows from a table.', 'Compare the saved customer address with what the profile page displayed.', ['Use queries carefully.', 'SELECT reads data; other commands may change it.', 'Practice on a safe test database.']],
  'SELECT': ['SELECT reads columns and rows from a database table.', 'Combine it with a table name and optional filters to inspect the data you need.', 'SELECT name, price FROM products lists product names and prices.', 'SELECT status, total FROM orders checks saved order values.', ['Reads data without changing it.', 'Choose only the columns you need.', 'Use filters for focused checks.']],
  'INSERT': ['INSERT adds a new row of data to a database table.', 'A test checks that valid values are stored and invalid values are rejected.', 'INSERT adds a new customer record with a unique email.', 'After creating an account, verify a matching user record was added.', ['Creates a record.', 'Check required fields and uniqueness.', 'Avoid writing to production data.']],
  'UPDATE': ['UPDATE changes one or more existing rows in a database table.', 'A WHERE condition is important so the change targets only the intended records.', 'UPDATE changes one product price by matching its ID.', 'After a profile edit, confirm only that user’s address changed.', ['Changes stored data.', 'Use a precise WHERE clause.', 'Verify intended and unintended rows.']],
  'DELETE': ['DELETE removes matching rows from a database table.', 'A safe test confirms the correct records are removed and related behavior remains consistent.', 'DELETE removes a test session by its unique ID.', 'After removing a saved address, check that it is absent from the account view.', ['Can permanently remove data.', 'Use precise conditions.', 'Check related records and permissions.']],
  'WHERE': ['WHERE filters rows so a query affects or returns only records matching a condition.', 'It is especially important in update and delete statements to avoid affecting every row.', 'SELECT * FROM orders WHERE status = "pending" returns pending orders.', 'Use WHERE user_id = 12 to inspect one test user’s orders.', ['Filters by a condition.', 'Combine conditions carefully.', 'Verify the result set before changing data.']],
  'JOIN': ['JOIN combines related rows from two or more tables using a matching relationship.', 'It lets a tester inspect connected data, such as an order together with its customer.', 'Join orders with customers using their customer IDs.', 'Join an order with its order items to verify the purchased products.', ['Uses related columns.', 'Different join types include inner and left joins.', 'Check for missing or duplicated matches.']],
  'Primary Key': ['A primary key uniquely identifies each row in a table.', 'It helps the database distinguish one record from another.', 'A customer ID identifies one customer even when names are identical.', 'Each order has a unique order ID for reliable lookup and update.', ['Must identify a row uniquely.', 'Should not be duplicated.', 'Other tables may refer to it.']],
  'Foreign Key': ['A foreign key is a field that refers to a key in another table and helps maintain a relationship.', 'It can help prevent records from pointing to a parent record that does not exist.', 'An order’s customer_id refers to a customer record.', 'Each cart item’s product_id should refer to a real product.', ['Connects related tables.', 'Supports referential integrity.', 'Test valid and invalid relationships.']],
  'CRUD Testing': ['CRUD testing checks the create, read, update, and delete operations for data.', 'Test each operation and confirm that the stored state matches what the application reports.', 'Create a note, read it, edit it, and delete it.', 'Add a cart item, view it, update quantity, and remove it.', ['C = Create, R = Read, U = Update, D = Delete.', 'Check both UI behavior and stored data.', 'Test permissions and invalid values.']],
  'Data Validation': ['Data validation checks that stored and displayed data is accurate, complete, and allowed by the rules.', 'Compare data across entry, storage, and output points.', 'Check that a saved date remains the same after it is read back.', 'Compare an order’s item count and total between checkout, confirmation, and account history.', ['Check accuracy and completeness.', 'Include formats, ranges, and relationships.', 'Protect data during testing.']],
  'Manual vs Automation Testing': ['Manual testing uses a person to perform checks; automation testing uses scripts or tools to execute checks.', 'Manual work is flexible for exploration; automation is repeatable for stable, frequent checks.', 'A person explores a new layout while a script repeats core sign-in checks on every build.', 'Manually review a fresh checkout design and automate the stable tax calculation cases.', ['Choose based on risk and repetition.', 'Automation has setup and maintenance costs.', 'Both approaches complement one another.']],
  'Advantages and Disadvantages': ['Automation can run checks quickly and repeatedly, but it costs time to build, debug, and maintain.', 'A stable, repeated check is often a good candidate; a rapidly changing visual experiment may not be.', 'Automated smoke checks can save release time, but brittle selectors can create maintenance work.', 'Automating a stable login flow helps frequent checks; automating every one-off layout idea may waste effort.', ['Benefits include speed and consistency.', 'Costs include setup and maintenance.', 'Automate valuable repeated checks first.']],
  'Automation Framework': ['An automation framework is a reusable structure for organizing test code, data, setup, and reporting.', 'It helps a team write consistent tests and maintain shared helpers.', 'A framework provides browser setup, common actions, assertions, and reports.', 'A shared framework can provide sign-in helpers and cart assertions to many tests.', ['Encourages consistency and reuse.', 'Should fit team needs.', 'Complexity should be justified by value.']],
  'Selenium Basics': ['Selenium is a browser automation toolset that can control browsers to exercise web applications.', 'A test locates elements, performs actions, and checks visible results.', 'A browser test opens a page, enters search text, and checks the results.', 'Use Selenium to fill a login form and assert that the account page is shown.', ['Controls supported browsers.', 'Tests interact with page elements.', 'Stable selectors and waits improve reliability.']],
  'Locators': ['Locators identify page elements so an automated test can interact with them.', 'Prefer stable identifiers such as a unique test ID or accessible label over fragile layout details.', 'A test locates a button by its accessible name “Save changes.”', 'Locate the checkout button by a stable data-testid attribute.', ['Identify one intended element.', 'Stable and meaningful locators reduce failures.', 'Avoid brittle position-based selectors.']],
  'Web Elements': ['Web elements are the interactive or informational pieces of a page, such as buttons, links, fields, and text.', 'Automation reads their state and performs actions on them.', 'A script finds a checkbox, selects it, and checks that it is selected.', 'Interact with the quantity input, update button, and cart total on a cart page.', ['Elements have attributes and states.', 'Actions should reflect user behavior.', 'Wait for dynamic elements to be ready.']],
  'Assertions': ['An assertion is a check in a test that compares an observed value with an expected condition.', 'A failed assertion signals that the test did not observe the expected behavior.', 'Assert that a successful sign-in displays the correct account heading.', 'Assert that updating a cart quantity changes the subtotal to the expected amount.', ['Assertions define pass or fail.', 'Check meaningful behavior.', 'Clear failure messages help debugging.']],
  'Waits': ['Waits help automation synchronize with a page that updates asynchronously.', 'A condition-based wait continues when an element is ready instead of relying on a fixed delay.', 'Wait until a confirmation message appears after a save action.', 'Wait for the cart total to update after changing an item quantity.', ['Prefer waiting for a condition.', 'Fixed sleeps can be slow and unreliable.', 'Set reasonable time limits.']],
  'Page Object Model': ['The Page Object Model organizes page-specific locators and actions in reusable objects separate from test intent.', 'This can make UI tests easier to read and update when a page changes.', 'A LoginPage object exposes methods to enter credentials and submit the form.', 'A CartPage object can provide add-item, update-quantity, and read-total methods.', ['Separates page mechanics from test goals.', 'Encourages reuse.', 'Avoid oversized objects with unrelated responsibilities.']],
  'unittest': ['unittest is Python’s built-in testing framework, with test cases, assertions, and setup or cleanup methods.', 'It lets Python developers organize checks into classes and run them with the standard library.', 'A TestCase verifies that a calculator returns the expected sum.', 'A Django helper can use unittest-style assertions to check a response status.', ['Included with Python.', 'Provides TestCase and assertions.', 'Tests are commonly named with a test prefix.']],
  'pytest': ['pytest is a Python testing framework known for concise test functions, fixtures, and a rich plugin ecosystem.', 'It discovers tests and reports failures with useful detail.', 'A function named test_total checks a calculated order amount.', 'Use pytest to run tests for a Django view and inspect a failed assertion.', ['Tests can be plain functions.', 'Fixtures provide reusable setup.', 'Plugins extend capabilities.']],
  'Assertions': ['An assertion checks that an observed value matches an expected condition.', 'When the condition is false, the test reports a failure at the point of mismatch.', 'assert add(2, 3) == 5 checks a calculator result.', 'Assert that a view response has status 200 and contains the expected profile name.', ['State expected behavior clearly.', 'Use assertions close to the relevant action.', 'Good failure output speeds diagnosis.']],
  'Test Functions': ['A test function is a small callable block that performs a setup, action, and verification for one behavior.', 'Clear names explain the condition being checked and the expected outcome.', 'test_empty_cart_shows_helpful_message checks one cart behavior.', 'test_profile_update_saves_new_name verifies a profile update.', ['Use descriptive names.', 'Keep each test focused.', 'Make setup and assertions understandable.']],
  'Test Classes': ['A test class groups related tests and can share setup or cleanup behavior.', 'It is useful when tests exercise the same component or need a common environment.', 'A CalculatorTests class groups addition and division checks.', 'A ProfileViewTests class groups cases for profile access and edits.', ['Group tests by behavior or component.', 'Keep shared setup minimal.', 'Independent tests are easier to run and debug.']],
  'Fixtures': ['A fixture provides reusable setup data or resources for tests and can manage cleanup.', 'Fixtures reduce repetition while making test dependencies visible.', 'A fixture creates a temporary user for several account tests.', 'A Django fixture can create a test product and remove its data after the test.', ['Fixtures can set up and tear down resources.', 'Keep them focused and reusable.', 'Avoid hidden coupling between tests.']],
  'Parameterization': ['Parameterization runs the same test logic against several input and expected-result pairs.', 'It is useful for boundary values and similar cases without copy-pasting tests.', 'A password validator is tested with short, valid, and too-long inputs.', 'Run the same discount test with several prices and expected totals.', ['Reuses one test structure.', 'Makes data variations visible.', 'Keep each case easy to understand.']],
  'Mocking': ['Mocking replaces a dependency with a controlled test double so a test can focus on one unit of behavior.', 'A mock can return a chosen response or record how it was called.', 'A unit test mocks an email service instead of sending a real message.', 'Mock the payment provider to simulate approval and decline responses safely.', ['Controls dependencies in isolation.', 'Can simulate hard-to-trigger outcomes.', 'Also test important integrations with real or realistic components.']],
  'Test Coverage': ['Test coverage measures which parts of a system or requirements were exercised by a set of tests.', 'Coverage can reveal untested areas, but a high number does not guarantee meaningful tests.', 'A report shows that a branch handling refunds has never run in tests.', 'A coverage report points to an untested error path in the order endpoint.', ['Coverage is a clue, not proof of quality.', 'Different measures cover code or requirements.', 'Test behavior and risk, not only percentages.']],
  'Django TestCase': ['Django TestCase provides a test environment and assertions for testing Django applications.', 'It can create isolated test data and send requests through Django’s test client.', 'A test checks that a product view returns the expected status.', 'Use the test client to submit a registration request and inspect the response.', ['Builds on Python testing tools.', 'Provides test database support.', 'Test behavior without running a live server.']],
  'Testing Models': ['Model tests check data rules and behavior defined by Django models.', 'They can verify field constraints, relationships, and custom model methods.', 'A test confirms that a product’s formatted display includes its currency.', 'Check that an order total method returns the sum of its line items.', ['Test model logic and constraints.', 'Include boundary and invalid values.', 'Use isolated test records.']],
  'Testing Views': ['View tests check how a Django view handles a request and constructs a response.', 'They can cover status codes, rendered content, redirects, and permissions.', 'A test requests a page and confirms it returns status 200.', 'Check that the account view redirects a signed-out visitor to sign-in.', ['Exercise requests and responses.', 'Check access rules and output.', 'Use the Django test client.']],
  'Testing URLs': ['URL tests check that paths resolve to the intended view and handle parameters correctly.', 'They catch routing mistakes that can make a valid page unreachable.', 'A test reverses a named URL and checks its path.', 'Confirm that /orders/42/ routes to the order detail view for order 42.', ['Use named URLs where possible.', 'Check parameters and invalid paths.', 'Confirm the intended view is reached.']],
  'Testing Forms': ['Form tests check validation, cleaned data, and error messages for submitted input.', 'Try both valid and invalid data and verify what the form accepts.', 'A form accepts a valid email and rejects a malformed one with a clear error.', 'Check that a checkout address form rejects a missing postal code.', ['Test valid and invalid submissions.', 'Verify field and form-level rules.', 'Check clear, useful validation messages.']],
  'Testing APIs': ['Django API tests check endpoint behavior, request validation, permissions, and response data.', 'They exercise an API through requests and compare the result with the contract.', 'A test posts valid JSON and checks for a created response.', 'Check that an order endpoint validates quantity and returns the expected JSON.', ['Cover methods and status codes.', 'Check data shape and authorization.', 'Include invalid requests.']],
  'Authentication Testing': ['Authentication testing checks sign-in, sign-out, identity, and access behavior.', 'Verify both successful access and safe handling of invalid or unauthorized attempts.', 'A valid user can sign in while an incorrect password is rejected.', 'Check that one shopper cannot open another shopper’s order URL.', ['Test valid, invalid, and expired credentials.', 'Check authorization separately from identity.', 'Protect accounts and private data.']],
  'Database Testing': ['Database testing checks stored data, constraints, relationships, and database-backed application behavior.', 'It verifies that data changes are correct and consistent.', 'A test confirms that an order has the expected customer and line items.', 'Check that deleting a test user follows the intended behavior for their orders.', ['Test constraints and relationships.', 'Use isolated test databases.', 'Verify transaction and cleanup behavior.']],
  'pytest-django': ['pytest-django connects pytest with Django so tests can use Django settings, test databases, and request tools.', 'It combines pytest fixtures and discovery with Django-specific helpers.', 'A test marked for database use can create a model record and query it.', 'Use a Django client fixture to test an API view with an authenticated user.', ['Requires correct Django settings.', 'Provides database and client fixtures.', 'Keep database access explicit in tests.']],
};

const moduleLens = {
  1: { focus: 'how teams build confidence in software', example: 'a sign-in or checkout flow', points: ['Start from user expectations.', 'Look for both expected and surprising behavior.', 'Share clear evidence with the team.'] },
  2: { focus: 'the stages and feedback loops used to build and test software', example: 'a feature moving from an idea to a supported release', points: ['Know what work happens at each stage.', 'Plan testing early.', 'Use feedback to improve the next step.'] },
  3: { focus: 'the lens a tester uses to evaluate software', example: 'a shopping journey viewed through behavior, implementation, and quality', points: ['Choose a technique that matches the risk.', 'Consider inputs, outputs, and context.', 'Different approaches can complement one another.'] },
  4: { focus: 'the scope of a check, from a small component to a complete product', example: 'an online order checked from a calculation to an end-to-end purchase', points: ['Test at several scopes.', 'Find problems as close as possible to their source.', 'Use broader checks to confirm parts work together.'] },
  5: { focus: 'the purpose and timing of a practical testing activity', example: 'a new release and the changes it contains', points: ['Choose the check based on the change and risk.', 'Keep expected outcomes clear.', 'Combine focused checks with broader coverage.'] },
  6: { focus: 'choosing representative inputs and workflows without testing every possibility', example: 'an input field with accepted ranges and business rules', points: ['Reduce a large input space thoughtfully.', 'Pay special attention to boundaries and combinations.', 'Explain why each test case was selected.'] },
  7: { focus: 'quality attributes beyond whether a feature returns the right answer', example: 'a popular service during a busy period', points: ['Define measurable goals.', 'Use realistic conditions.', 'Observe impact on users and system resources.'] },
  8: { focus: 'making checks repeatable and easy for another person to follow', example: 'a saved-cart or account workflow', points: ['State the starting conditions.', 'Use concrete data and steps.', 'Compare observable results with expectations.'] },
  9: { focus: 'communicating and tracking a product problem until it is resolved', example: 'a customer-facing order issue', points: ['Describe impact and conditions.', 'Make reproduction steps precise.', 'Verify fixes and look for side effects.'] },
  10: { focus: 'testing as part of a collaborative, iterative product team', example: 'a small customer-facing improvement in a sprint', points: ['Collaborate early.', 'Turn stories into testable examples.', 'Give the team feedback throughout the sprint.'] },
  11: { focus: 'checking data and behavior exchanged between software services', example: 'a product or order endpoint', points: ['Check request, response, and status together.', 'Try valid, invalid, and unauthorized requests.', 'Use safe test credentials and data.'] },
  12: { focus: 'checking the records and relationships that support an application', example: 'customers, products, carts, and orders', points: ['Check stored values against what users see.', 'Test relationships and constraints.', 'Use a safe, isolated test database.'] },
  13: { focus: 'reliable browser checks and maintainable test code', example: 'a stable sign-in or cart journey', points: ['Automate valuable repeated checks.', 'Use stable locators and clear assertions.', 'Keep tests independent and maintainable.'] },
  14: { focus: 'writing readable and repeatable checks with Python', example: 'a small function or service behavior', points: ['Keep tests focused.', 'Use fixtures and data variations deliberately.', 'Make failures easy to understand.'] },
  15: { focus: 'checking a Django application at its model, view, route, and API boundaries', example: 'a small account or order feature', points: ['Test behavior at the right layer.', 'Use isolated test data and database support.', 'Check permissions as well as successful paths.'] },
};

const pickExample = (moduleNumber, title) => {
  const lens = moduleLens[moduleNumber];
  const examples = [
    `Imagine ${lens.example}: a tester checks “${title}” by setting up a realistic situation, performing the relevant action, and observing what the system does.`,
    `A team changing ${lens.example} can use “${title}” to decide what to check before it releases the change.`,
    `When something goes wrong in ${lens.example}, “${title}” gives the team a structured way to investigate the behavior and its impact.`,
  ];
  return examples[(title.length + moduleNumber) % examples.length];
};

export function getLesson(topic) {
  if (!topic) return null;
  const module = getModule(topic.moduleId);
  const lens = moduleLens[topic.moduleNumber];
  const specific = topic.title === 'Assertions' && topic.moduleNumber === 13
    ? ['In an automated test, an assertion compares an observed value with an expected condition.', 'An assertion is the check that tells a browser test whether the page behaved as expected.', 'A test asserts that a successful sign-in displays the account home page.', 'Assert that the cart subtotal changes to the expected amount after updating quantity.', ['Assertions define pass or fail.', 'Check meaningful user behavior.', 'A clear failure message helps debugging.']]
    : topic.title === 'DELETE' && topic.moduleNumber === 11
      ? ['A DELETE request asks an API to remove a resource or make it unavailable.', 'Check who is allowed to delete, what response comes back, and what later reads show.', 'DELETE /saved-trips/7 removes one saved trip.', 'DELETE /api/cart/items/8 removes the selected item from the cart.', ['Check access permissions.', 'Confirm the resource no longer appears as expected.', 'Verify repeated deletion behavior against the API contract.']]
      : core[topic.title];
  const definition = specific?.[0] ?? `${topic.title} is a practical concept in ${module.title.toLowerCase()} that helps a team make a clearer, more reliable decision about software quality.`;
  const explanation = specific?.[1] ?? `Think of “${topic.title}” as one way to work with ${lens.focus}. The useful question is: what should happen, under which conditions, and how will we recognize the result?`;
  const realWorldExample = specific?.[2] ?? pickExample(topic.moduleNumber, topic.title);
  const appExample = specific?.[3] ?? `In a web application, apply “${topic.title}” to the ${lens.example}: prepare the relevant account or data, perform the action, and check the visible result and any saved data.`;
  const keyPoints = specific?.[4] ?? lens.points;
  return {
    ...topic,
    definition,
    explanation,
    keyPoints,
    realWorldExample,
    appExample,
    terms: [topic.title, 'Expected result', 'Test data', 'Risk'],
    interviewQuestion: `What is ${topic.title}, and when would you use it while testing a software product?`,
    interviewHint: `Explain the idea in plain language, connect it to ${lens.focus}, and give a short example with an expected result.`,
    quickRevision: [definition, keyPoints[0], `Example to remember: ${realWorldExample}`],
  };
}
